//! `clone.py` + `ui/clone.ui` (`vmmCloneVM`): the Clone Virtual Machine
//! dialog — the new VM's name, a clone-or-share choice for every disk
//! with the "Change storage path" subdialog, and the clone job itself,
//! all on `virtinst_core::cloner::Cloner` (the port of
//! `virtinst/cloner.py` that `virt-clone` also drives).
//!
//! Upstream's v5.1.0 dialog has no networking section: the new VM's
//! MAC addresses are generated by `Cloner._init_new_guest` and not
//! shown.

use std::cell::{Cell, RefCell};
use std::collections::HashMap;
use std::rc::{Rc, Weak};

use gtk::prelude::*;
use gtk::{gio, glib};
use virtinst_core::cloner::{self, CloneDiskInfo, Cloner};
use virtinst_core::connection::Connection;

use crate::asyncjob;
use crate::connection::{ConnHandle, VmmConnection};
use crate::domain::VmmDomain;
use crate::error;
use crate::storagebrowse::StorageBrowser;

/// `_get_cloneable_msg`: is the passed path even clone-able.
fn get_cloneable_msg(diskinfo: &CloneDiskInfo) -> Option<String> {
    if let Some(msg) = diskinfo.get_cloneable_msg() {
        return Some(msg);
    }
    diskinfo
        .is_empty()
        .then(|| "No storage to clone.".to_string())
}

/// Python's `"%s" % value` for an optional string.
fn or_none(v: Option<&str>) -> &str {
    v.unwrap_or("None")
}

/// `_StorageInfo`: close to the cloner's `_CloneDiskInfo` content. All
/// user choices are tracked here, and serialized into the actual
/// cloner diskinfo once the user clicks 'Clone'.
#[derive(Clone, Debug, PartialEq)]
pub struct StorageInfo {
    target: Option<String>,
    orig_path: Option<String>,
    /// GiB.
    size: f64,
    icon_name: &'static str,
    orig_vm_name: String,
    new_vm_name: String,
    share_msg: Option<String>,
    cloneable_msg: Option<String>,
    manual_path: Option<String>,
    generated_path: Option<String>,
    clone_requested: bool,
}

impl StorageInfo {
    /// `__init__`, from a diskinfo of a cloner that ran `prepare()`.
    /// `conn`/`is_remote` check generated paths for collisions.
    fn new(
        conn: &virt::connect::Connect,
        is_remote: bool,
        orig_vm_name: &str,
        new_vm_name: &str,
        diskinfo: &CloneDiskInfo,
    ) -> StorageInfo {
        // `get_icon_name`
        let icon_name = if diskinfo.is_floppy() {
            "media-floppy"
        } else if diskinfo.is_cdrom() {
            "media-optical"
        } else {
            "drive-harddisk"
        };
        let mut sinfo = StorageInfo {
            target: diskinfo.target.clone(),
            orig_path: diskinfo.get_source_path(),
            size: diskinfo.get_size(),
            icon_name,
            orig_vm_name: orig_vm_name.into(),
            new_vm_name: new_vm_name.into(),
            share_msg: diskinfo.get_share_msg().map(str::to_string),
            cloneable_msg: get_cloneable_msg(diskinfo),
            manual_path: None,
            generated_path: diskinfo
                .new_disk
                .as_ref()
                .and_then(|d| d.get_source_path())
                .filter(|p| !p.is_empty())
                .map(str::to_string),
            clone_requested: diskinfo.is_clone_requested(),
        };
        if sinfo.generated_path.is_none() {
            sinfo.reset_generated_path(conn, is_remote);
        }
        if sinfo.share_msg.is_some() || !sinfo.is_cloneable() {
            sinfo.clone_requested = false;
        }
        sinfo
    }

    pub fn is_cloneable(&self) -> bool {
        self.cloneable_msg.is_none()
    }

    pub fn is_clone_requested(&self) -> bool {
        self.clone_requested
    }

    pub fn is_share_requested(&self) -> bool {
        !self.clone_requested
    }

    pub fn warn_about_sharing(&self) -> bool {
        self.share_msg.is_none()
    }

    pub fn get_target(&self) -> Option<&str> {
        self.target.as_deref()
    }

    pub fn get_orig_disk_path(&self) -> Option<&str> {
        self.orig_path.as_deref()
    }

    pub fn get_new_disk_path(&self) -> Option<&str> {
        self.manual_path
            .as_deref()
            .filter(|p| !p.is_empty())
            .or(self.generated_path.as_deref())
    }

    pub fn set_clone_requested(&mut self, val: bool) {
        self.clone_requested = val;
    }

    pub fn set_manual_path(&mut self, val: &str) {
        self.manual_path = Some(val.into());
    }

    /// `set_new_vm_name`, minus the path reset: whether the name
    /// changed, and the generated path needs [`Self::reset_generated_path`].
    pub fn set_new_vm_name(&mut self, val: &str) -> bool {
        if val.is_empty() || val == self.new_vm_name {
            return false;
        }
        self.new_vm_name = val.into();
        true
    }

    /// `_reset_generated_path` (`Cloner.generate_clone_disk_path`).
    fn reset_generated_path(&mut self, conn: &virt::connect::Connect, is_remote: bool) {
        self.generated_path = cloner::generate_clone_disk_path(
            conn,
            is_remote,
            Some(&self.orig_vm_name),
            &self.new_vm_name,
            self.orig_path.as_deref(),
        );
    }

    /// `set_values_on_diskinfo`, on disk `idx` of `cloner`.
    fn set_values_on_diskinfo(&self, cloner: &mut Cloner, idx: usize) {
        if !self.clone_requested {
            let diskinfo = &mut cloner.diskinfos_mut()[idx];
            diskinfo.set_share_requested();
            diskinfo.new_disk = None;
            return;
        }
        cloner.diskinfos_mut()[idx].set_clone_requested();
        let sparse = true;
        let newpath = self.get_new_disk_path().map(str::to_string);
        cloner.set_disk_new_path(idx, newpath.as_deref(), sparse);
    }

    /// `get_tooltip`.
    pub fn get_tooltip(&self) -> String {
        let mut lines = vec![
            format!("Disk target: {}", or_none(self.get_target())),
            format!("Original path: {}", or_none(self.get_orig_disk_path())),
        ];
        if let Some(new) = self.get_new_disk_path() {
            lines.push(format!("New path: {new}"));
        }
        lines.push("\n".into());

        match &self.share_msg {
            Some(reason) => lines.push(format!("Storage is safe to share: {reason}")),
            None => lines.push("Sharing this storage is potentially dangerous.".into()),
        }
        if let Some(reason) = &self.cloneable_msg {
            lines.push(format!("Storage is not cloneable: {reason}"));
        }
        lines.join("\n")
    }

    /// `get_markup`: the path, and what happens to it.
    pub fn get_markup(&self, vm_name: &str) -> String {
        // `if path:`
        let mut lines = vec![self
            .get_orig_disk_path()
            .filter(|p| !p.is_empty())
            .unwrap_or("No storage.")
            .to_string()];

        let mut line = String::new();
        if self.is_share_requested() {
            line += &format!("Share disk with {vm_name}");
        }
        if self.is_clone_requested() {
            line += "Clone this disk";
            let sizelabel = self.get_size_label();
            if !sizelabel.is_empty() {
                line += &format!(" ({sizelabel})");
            }
        }
        if !line.is_empty() {
            lines.push(line);
        }

        let label = lines.join("\n");
        format!("<small>{}</small>", glib::markup_escape_text(&label))
    }

    pub fn get_icon_name(&self) -> &'static str {
        self.icon_name
    }

    /// `get_size_label`.
    pub fn get_size_label(&self) -> String {
        if self.size == 0.0 {
            return String::new();
        }
        format!("{:.1} GiB", self.size)
    }
}

/// `_reset_state`'s cloner half: the names and the storage list, from a
/// cloner that hasn't run `prepare()` yet.
fn collect_storage(cloner: &mut Cloner) -> Result<(String, String, Vec<StorageInfo>), String> {
    cloner.prepare()?;
    let (src_name, new_name) = (cloner.src_name().to_string(), cloner.new_name());
    let conn = cloner.conn().as_connect();
    let is_remote = cloner.conn().uri().is_remote();
    let list = cloner
        .diskinfos()
        .iter()
        .map(|d| StorageInfo::new(conn, is_remote, &src_name, &new_name, d))
        .collect();
    Ok((src_name, new_name, list))
}

/// `_build_final_cloner`'s cloner half: the user's choices from
/// `list` on every disk, then `prepare()` and each disk's errors.
fn apply_storage(cloner: &mut Cloner, list: &[StorageInfo]) -> Result<(), String> {
    for idx in 0..cloner.diskinfos().len() {
        let target = cloner.diskinfos()[idx].target.clone();
        // A KeyError upstream, shown as the quoted key.
        let sinfo = list
            .iter()
            .find(|s| s.target == target)
            .ok_or_else(|| format!("'{}'", or_none(target.as_deref())))?;
        sinfo.set_values_on_diskinfo(cloner, idx);
    }
    cloner.prepare()?;
    for diskinfo in cloner.diskinfos() {
        diskinfo.raise_error()?;
    }
    Ok(())
}

/// `_validate`'s list of the shared disks it warns about.
fn share_warnings(list: &[StorageInfo]) -> String {
    list.iter()
        .filter(|s| !s.is_clone_requested() && s.warn_about_sharing())
        .map(|s| {
            format!(
                "{}: {}\n",
                or_none(s.get_target()),
                or_none(s.get_orig_disk_path())
            )
        })
        .collect()
}

/// `_finish`'s progress window title and text.
fn job_title_text(new_name: &str, has_nonshare: bool) -> (String, String) {
    let title = format!("Creating virtual machine clone '{new_name}'");
    let text = if has_nonshare {
        format!(
            "Creating virtual machine clone '{new_name}' and selected storage (this may take a while)"
        )
    } else {
        title.clone()
    };
    (title, text)
}

/// `_build_cloner`, on our own reference to the open connection
/// (`conn.get_backend()`).
fn build_cloner(
    handle: &ConnHandle,
    uri: &str,
    orig_name: &str,
    new_name: &str,
) -> Result<Cloner<'static>, String> {
    let conn = Connection::from_connect(handle.connect().clone(), uri);
    let mut cloner = Cloner::new_owned(conn, Some(orig_name), None)?;
    if !new_name.is_empty() {
        cloner.set_clone_name(new_name);
    }
    Ok(cloner)
}

/// `_async_clone`: duplicate, then refresh the pools that got new
/// volumes.
fn async_clone(
    job: asyncjob::JobHandle,
    cloner: Cloner<'static>,
) -> Result<(), asyncjob::JobError> {
    let mut meter = job.meter();

    let mut refresh_pools: Vec<String> = vec![];
    for idx in cloner.nonshare_indexes() {
        let Some(pool) = cloner.diskinfos()[idx]
            .new_disk
            .as_ref()
            .and_then(|d| d.get_parent_pool())
        else {
            continue;
        };
        if !refresh_pools.contains(&pool.xml.name) {
            refresh_pools.push(pool.xml.name.clone());
        }
    }

    cloner
        .start_duplicate(&mut meter)
        .map_err(|e| (e.clone(), e))?;

    let conn = cloner.conn().as_connect();
    for poolname in refresh_pools {
        match virt::storage_pool::StoragePool::lookup_by_name(conn, &poolname) {
            Ok(pool) => {
                let _ = pool.refresh(0);
            }
            Err(_) => {
                eprintln!("Error looking up pool={poolname} for refresh after VM clone.")
            }
        }
    }
    Ok(())
}

fn lighter_label(text: &str, halign: gtk::Align) -> gtk::Label {
    let l = gtk::Label::with_mnemonic(text);
    l.set_halign(halign);
    l.add_css_class("vmm-lighter");
    l
}

