        table5.attach(&size_label, 0, 2, 1, 1);
        table5.attach(&size, 1, 2, 1, 1);
        let label1 = gtk::Label::new(Some("Existing disk"));
        label1.set_halign(gtk::Align::Start);
        let image2 = gtk::Image::from_icon_name("drive-harddisk");
        image2.set_pixel_size(48);
        image2.set_margin_start(18);
        image2.set_margin_end(18);
        let table4 = gtk::Grid::new();
        table4.set_row_spacing(6);
        table4.set_column_spacing(6);
        table4.attach(&label1, 0, 0, 2, 1);
        table4.attach(&image2, 0, 1, 1, 1);
