        let new_label = gtk::Label::with_mnemonic("New _Path:");
        new_label.set_halign(gtk::Align::End);
        new_label.set_mnemonic_widget(Some(&new));
        let table3 = gtk::Grid::new();
        table3.set_margin_start(6);
        table3.set_margin_end(6);
        table3.set_margin_top(6);
        table3.set_margin_bottom(6);
        table3.set_row_spacing(6);
        table3.set_column_spacing(6);
        table3.set_vexpand(true);
        table3.attach(&doclone, 0, 0, 3, 1);
        table3.attach(&new_label, 0, 1, 1, 1);
        table3.attach(&new, 1, 1, 1, 1);
